    "gst_rule_1":"জুয়েলারের কাছ থেকে গয়না কিনলে: পুরো বিলের ওপর 3% GST, মানে ধাতু, মজুরি, ওয়েস্টেজ আর পাথর মিলিয়ে, মজুরি আলাদা লেখা থাকলেও। নিজের রাজ্যে এটি CGST 1.5% + SGST 1.5%। GST 2.0 (22 সেপ্টেম্বর 2025)-এ এই রেট বদলায়নি।",
    "gst_rule_2":"নিজের সোনা দিয়ে গয়না বানালে (জব ওয়ার্ক): মজুরির ওপর 5% GST, আর যোগ করা বাড়তি সোনায় 3%। কিছু জুয়েলার GST রেজিস্ট্রেশন নেই এমন ক্রেতার কাছ থেকে মজুরিতে 18% নেন, তাই বিলে লেখা রেটটি বেছে নিন।",
    "gst_rule_3":"পুরোনো সোনা বদলালে: GST নতুন গয়নার দামের ওপর লাগে; পুরোনো সোনা আংশিক দাম হিসেবে ধরা হয়। ব্যবসার কেনাকাটা বা সন্দেহ থাকলে আপনার CA-কে জিজ্ঞেস করুন।",
