    "gst_rule_1":"ઝવેરી પાસેથી દાગીનો ખરીદો ત્યારે: આખા બિલ પર 3% GST, એટલે ધાતુ, ઘડામણ, ઘટ અને નંગ બધું મળીને, ઘડામણ અલગ લખ્યું હોય તો પણ. પોતાના રાજ્યમાં CGST 1.5% + SGST 1.5%. GST 2.0 (22 સપ્ટેમ્બર 2025)માં આ દર બદલાયો નથી.",
