    "gst_rule_3":"ਪੁਰਾਣਾ ਸੋਨਾ ਬਦਲਣ 'ਤੇ: GST ਨਵੇਂ ਗਹਿਣੇ ਦੀ ਕੀਮਤ 'ਤੇ ਲੱਗਦਾ ਹੈ; ਪੁਰਾਣਾ ਸੋਨਾ ਅੰਸ਼ਕ ਭੁਗਤਾਨ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ। ਕਾਰੋਬਾਰੀ ਖ਼ਰੀਦ ਜਾਂ ਸ਼ੱਕ ਹੋਵੇ ਤਾਂ ਆਪਣੇ CA ਨੂੰ ਪੁੱਛੋ।",
