    "how_2":"ਬੋਰਡ ਦਾ ਰੇਟ 24K ਦਾ ਹੈ? \"24K 999: ਮੇਰੀ ਸ਼ੁੱਧਤਾ ਦਾ ਰੇਟ ਕੱਢੋ\" ਚੁਣੋ, 22K ਜਾਂ 18K ਰੇਟ ਆਪਣੇ ਆਪ ਨਿਕਲ ਆਵੇਗਾ।",
    "how_3":"2-3 ਦੁਕਾਨਾਂ ਤੋਂ ਭਾਅ ਲੈ ਰਹੇ ਹੋ? ਦੁਕਾਨਾਂ ਦੀ ਤੁਲਨਾ ਵਰਤੋ: ਘੱਟ ਰੇਟ 'ਤੇ ਵੱਧ ਘੜਾਈ ਜਾਂ ਵੇਸਟੇਜ ਅਕਸਰ ਮਹਿੰਗਾ ਪੈਂਦਾ ਹੈ।",
    "how_4":"ਪੁਰਾਣਾ ਸੋਨਾ ਬਦਲ ਰਹੇ ਹੋ? ਪੁਰਾਣਾ ਸੋਨਾ ਬਦਲੋ ਟੈਬ ਵਿੱਚ \"ਗਹਿਣੇ ਦੀ ਕੀਮਤ ਟੈਬ ਦਾ ਕੁੱਲ ਲਓ\" ਦਬਾਓ ਅਤੇ ਵੇਖੋ ਕਿ ਠੀਕ ਕਿੰਨਾ ਦੇਣਾ ਹੈ।",
