    "how_6":"ਤੁਹਾਡੇ ਆਖ਼ਰੀ ਰੇਟ ਅਤੇ ਸੈਟਿੰਗਾਂ ਇਸੇ ਫ਼ੋਨ 'ਤੇ ਸੇਵ ਰਹਿੰਦੀਆਂ ਹਨ। ਰੇਟ ਰੋਜ਼ ਬਦਲਦੇ ਹਨ, ਇਸ ਲਈ ਵਰਤਣ ਤੋਂ ਪਹਿਲਾਂ ਬਦਲ ਲਓ।",
