    "gst_rule_title":"ବ୍ୟବହୃତ GST ନିୟମ (ଅକ୍ଟୋବର 2026)",
    "gst_rule_1":"ଜୁଏଲରଙ୍କଠାରୁ ଗହଣା କିଣିଲେ: ପୂରା ବିଲ୍ ଉପରେ 3% GST, ଅର୍ଥାତ୍ ଧାତୁ, ମଜୁରି, ୱେଷ୍ଟେଜ୍ ଓ ପଥର ମିଶି, ମଜୁରି ଅଲଗା ଲେଖାଥିଲେ ମଧ୍ୟ। ନିଜ ରାଜ୍ୟରେ CGST 1.5% + SGST 1.5%। GST 2.0 (22 ସେପ୍ଟେମ୍ବର 2025) ରେ ଏହି ଦର ବଦଳିନାହିଁ।",
    "gst_rule_2":"ନିଜ ସୁନାରୁ ଗହଣା (ଜବ୍ ୱାର୍କ): ମଜୁରିରେ 5% GST, ଓ ଯୋଡ଼ାଯାଇଥିବା ଅତିରିକ୍ତ ସୁନାରେ 3%। କିଛି ଜୁଏଲର GST ପଞ୍ଜୀକରଣ ନଥିବା ଗ୍ରାହକଙ୍କଠାରୁ ମଜୁରିରେ 18% ନିଅନ୍ତି, ତେଣୁ ବିଲରେ ଲେଖାଥିବା ଦର ବାଛନ୍ତୁ।",
    "gst_rule_3":"ପୁରୁଣା ସୁନା ବଦଳାଇଲେ: GST ନୂଆ ଗହଣାର ଦାମ ଉପରେ ଲାଗେ; ପୁରୁଣା ସୁନା ଆଂଶିକ ପେମେଣ୍ଟ ଭାବେ ଧରାଯାଏ। ବ୍ୟବସାୟ କିଣାକିଣି ବା ସନ୍ଦେହ ଥିଲେ ଆପଣଙ୍କ CA ଙ୍କୁ ପଚାରନ୍ତୁ।",
