    "tl_own_value":"இன்று உங்கள் தங்கத்தின் மதிப்பு",
    "msg_above":"நீங்கள் {x} செலுத்துகிறீர்கள், உலோக விலை {r}-ஐ விட {p}% அதிகம். விற்கும்போது செய்கூலி, சேதாரம், GST பொதுவாகத் திரும்பக் கிடைக்காது.",
