    "gst_short":"GST: நகையின் முழு மதிப்பில் 3% (CGST 1.5% + SGST 1.5%).",
    "share_footer":"AI பாடசாலையில் சரிபார்த்தது:",
    "print_note":"மதிப்பீடு மட்டுமே. கடை பில்லுடன் ஒப்பிடுங்கள்.",
    "gst_rule_title":"பின்பற்றிய GST விதி (அக்டோபர் 2026)",
    "gst_rule_1":"கடையில் நகை வாங்கினால்: முழு பில் மதிப்பில் 3% GST, அதாவது உலோகம், செய்கூலி, சேதாரம், கற்கள் அனைத்தும் சேர்த்து, செய்கூலி தனியாக எழுதியிருந்தாலும். உங்கள் மாநிலத்தில் CGST 1.5% + SGST 1.5%. GST 2.0 (22 செப்டம்பர் 2025) இந்த விகிதத்தை மாற்றவில்லை.",
    "gst_rule_2":"சொந்தத் தங்கத்தில் நகை (ஜாப் வொர்க்): செய்கூலிக்கு 5% GST, சேர்த்த கூடுதல் தங்கத்துக்கு 3%. சில கடைகள் GST பதிவு இல்லாத வாடிக்கையாளர்களிடம் கூலிக்கு 18% வசூலிக்கின்றன; பில்லில் உள்ள விகிதத்தைத் தேர்ந்தெடுங்கள்.",
    "gst_rule_3":"பழைய தங்க மாற்றம்: GST புதிய நகையின் விலையில் விதிக்கப்படும்; பழைய தங்கம் பகுதிப் பணமாகக் கணக்கிடப்படும். வணிக வாங்கல் அல்லது சந்தேகம் என்றால் உங்கள் CA-விடம் கேளுங்கள்.",
    "ex_title":"உங்கள் பழைய தங்கத்தின் மதிப்பு",
    "ex_weight":"பழைய நகை எடை",
    "ex_purity":"தூய்மை (சோதித்தபடி)",
    "ex_purity_hint":"கடையில் உங்கள் முன்னால் காரட் மீட்டரில் (XRF) சோதிக்கச் சொல்லுங்கள். பழைய நகைகள் நினைப்பதைவிடக் குறைந்த தூய்மையாக இருக்கலாம்.",
    "ex_ded":"கழிவு (உருக்கும் இழப்பு)",
    "ex_ded_hint":"பொதுவாக 0 முதல் 5%. அதே கடையில் வாங்கிய நகைக்குக் குறைவு. சோதிக்கும் முன் கேளுங்கள்.",
    "ex_new_label":"புதிய நகையின் மொத்தம் (விருப்பம், ₹)",
