    "ex_refund":"கடை உங்களுக்குத் தரும்",
    "ex_note":"புதிய நகை கழித்தல் பழைய தங்கம் = செலுத்த வேண்டியது. GST புதிய நகையின் முழு விலையிலேயே இருக்கும். பழைய நகையின் கற்களுக்குப் பொதுவாகப் பணம் கிடைக்காது.",
    "cmp_title":"3 கடைகள் வரை ஒப்பிடுங்கள்",
    "cmp_intro":"ஒவ்வொரு கடையிலும் ஒரே டிசைன், தூய்மைக்கு விலை கேளுங்கள். அவர்களின் விலை, செய்கூலி, சேதாரத்தை உள்ளிட்டு 3% GST-க்குப் பின் உண்மையில் மலிவு எது எனப் பாருங்கள்.",
