    "gst_rule_title":"ಬಳಸಿದ GST ನಿಯಮ (ಅಕ್ಟೋಬರ್ 2026)",
    "gst_rule_1":"ಅಂಗಡಿಯಲ್ಲಿ ಆಭರಣ ಖರೀದಿಸಿದರೆ: ಪೂರ್ಣ ಬಿಲ್ ಮೌಲ್ಯದ ಮೇಲೆ 3% GST, ಅಂದರೆ ಲೋಹ, ಮಜೂರಿ, ವೇಸ್ಟೇಜ್, ಕಲ್ಲು ಎಲ್ಲಾ ಸೇರಿ, ಮಜೂರಿ ಬೇರೆಯಾಗಿ ಬರೆದಿದ್ದರೂ. ನಿಮ್ಮ ರಾಜ್ಯದಲ್ಲಿ CGST 1.5% + SGST 1.5%. GST 2.0 (22 ಸೆಪ್ಟೆಂಬರ್ 2025) ಈ ದರ ಬದಲಿಸಿಲ್ಲ.",
    "gst_rule_2":"ನಿಮ್ಮದೇ ಚಿನ್ನದಿಂದ ಆಭರಣ (ಜಾಬ್ ವರ್ಕ್): ಮಜೂರಿಯ ಮೇಲೆ 5% GST, ಸೇರಿಸಿದ ಹೆಚ್ಚುವರಿ ಚಿನ್ನಕ್ಕೆ 3%. ಕೆಲವು ಅಂಗಡಿಗಳು GST ನೋಂದಣಿ ಇಲ್ಲದ ಗ್ರಾಹಕರಿಂದ ಕೂಲಿಗೆ 18% ತೆಗೆದುಕೊಳ್ಳುತ್ತವೆ, ಆದ್ದರಿಂದ ಬಿಲ್‌ನಲ್ಲಿರುವ ದರ ಆಯ್ಕೆಮಾಡಿ.",
