    "ck_2_t":"HUID ಪರಿಶೀಲಿಸಿ.",
    "ck_2_d":" ಉಚಿತ BIS CARE ಆ್ಯಪ್‌ನಲ್ಲಿ HUID ನಮೂದಿಸಿ (\"Verify HUID\"). ಶುದ್ಧತೆ, ಆಭರಣದ ಪ್ರಕಾರ ಮತ್ತು ಅಂಗಡಿ ಕಾಣುತ್ತದೆ. ಬಿಲ್ ಜೊತೆ ಹೊಂದಬೇಕು.",
