    "ck_3_d":" 22K ಗೆ 916, 18K ಗೆ 750, 14K ಗೆ 585. ಆ ಶುದ್ಧತೆಗೆ ಯಾವ ದರ ಹಾಕಿದರು ಕೇಳಿ.",
