    "print_note":"ഏകദേശ കണക്ക് മാത്രം. കടയിലെ ബില്ലുമായി ഒത്തുനോക്കൂ.",
    "gst_rule_title":"പാലിച്ച GST നിയമം (ഒക്ടോബർ 2026)",
    "gst_rule_1":"ജ്വല്ലറിയിൽ നിന്ന് ആഭരണം വാങ്ങുമ്പോൾ: മുഴുവൻ ബിൽ മൂല്യത്തിൽ 3% GST, അതായത് ലോഹം, പണിക്കൂലി, പണിക്കുറവ്, കല്ലുകൾ എല്ലാം ചേർത്ത്, പണിക്കൂലി വേറെ എഴുതിയാലും. സ്വന്തം സംസ്ഥാനത്ത് CGST 1.5% + SGST 1.5%. GST 2.0 (22 സെപ്റ്റംബർ 2025) ഈ നിരക്ക് മാറ്റിയില്ല.",
    "gst_rule_2":"സ്വന്തം സ്വർണത്തിൽ ആഭരണം (ജോബ് വർക്ക്): പണിക്കൂലിക്ക് 5% GST, ചേർത്ത അധിക സ്വർണത്തിന് 3%. ചില ജ്വല്ലറികൾ GST രജിസ്ട്രേഷൻ ഇല്ലാത്തവരിൽ നിന്ന് കൂലിക്ക് 18% ഈടാക്കുന്നു, അതിനാൽ ബില്ലിലെ നിരക്ക് തിരഞ്ഞെടുക്കൂ.",
    "gst_rule_3":"പഴയ സ്വർണം മാറ്റൽ: GST പുതിയ ആഭരണത്തിന്റെ വിലയിലാണ്; പഴയ സ്വർണം ഭാഗിക പണമായി കണക്കാക്കും. ബിസിനസ് വാങ്ങലോ സംശയമോ ഉണ്ടെങ്കിൽ നിങ്ങളുടെ CA-യോട് ചോദിക്കൂ.",
    "ex_title":"നിങ്ങളുടെ പഴയ സ്വർണത്തിന്റെ മൂല്യം",
    "ex_weight":"പഴയ ആഭരണത്തിന്റെ തൂക്കം",
    "ex_purity":"പരിശുദ്ധി (പരിശോധിച്ചത്)",
    "ex_purity_hint":"കടയിൽ നിങ്ങളുടെ മുന്നിൽ കാരറ്റ് മീറ്ററിൽ (XRF) പരിശോധിപ്പിക്കൂ. പഴയ ആഭരണങ്ങൾ പലപ്പോഴും കരുതിയതിനേക്കാൾ കുറഞ്ഞ പരിശുദ്ധിയായിരിക്കും.",
    "ex_ded":"കിഴിവ് (ഉരുക്കൽ നഷ്ടം)",
    "ex_ded_hint":"സാധാരണ 0 മുതൽ 5%. അതേ കടയിൽ നിന്ന് വാങ്ങിയതിന് പലപ്പോഴും കുറവ്. പരിശോധനയ്ക്ക് മുമ്പ് ചോദിക്കൂ.",
