    "ck_1_d":" സ്വർണാഭരണത്തിൽ BIS ത്രികോണ ലോഗോ, പരിശുദ്ധി ഗ്രേഡ് (ഉദാ. 22K916), 6 അക്ഷര HUID കോഡ് ഉണ്ടാകണം.",
    "ck_2_t":"HUID പരിശോധിക്കൂ.",
    "ck_2_d":" സൗജന്യ BIS CARE ആപ്പിൽ HUID നൽകൂ (\"Verify HUID\"). പരിശുദ്ധി, ആഭരണ തരം, ജ്വല്ലറി കാണാം. ബില്ലുമായി ഒത്തുപോകണം.",
